// tests/fixtures/claims-r13-states.ts — J-M01: one entry per section-A state of docs/ops/CLAIMS-T49-ROUND13-SPEC-v1.md.
//
// Each entry carries (1) the ten expected fields of its A row and the E registry ids its row names (TEXT, generated
// from the frozen spec with the withdrawn-guard vocabulary removed), and (2) the executable facts of the state
// (FACTS, written by hand): an order world over tests/support/claims-world, what the REAL engine answers on it
// (J-M03 fresh refund, J-M04 resume-first), and what reconcile's no-row derivation writes (J-M43).
//
// IMPLEMENTATION NOTE (W3) on J-M01: the spec addendum docs/ops/CLAIMS-T49-FAIL-CLOSED-RECOVERY.md carries no round-13
// table (it names no A-S id), so the id list is the frozen spec's own section-A headings; A-S00 (conventions) is not a
// state and has no entry.
import { refundRow, stripeRefund, HOURS, type World } from '../support/claims-world'
import { royaltyRow, type EngineWorld } from '../support/claims-engine-world'
import type { RegistryId, PendingEvidence } from '@/lib/claim-action-rules'

export type StateExpected = {
  stripe: string; dbRefunds: string; claim: string; engineAccepts: string; engineResumes: string
  safeExit: string; newMoney: string; customer: string; admin: string; reconciliation: string
}

/** A-S00: the engine's answers, quoted from lib/refund.ts. */
export const ENGINE_QUOTES = {
  E1:  { status: 409, message: 'Commande non payée — rien à rembourser.' },
  E2:  { status: 409, message: 'Remboursement précédent en échec sur cette commande — reprise manuelle requise (Dashboard Stripe : re-transférer le net au restaurant, puis rembourser sans reverse_transfer).' },
  PIX: { status: 502, message: 'Erreur paiement, réessayez.' },
  E1b: { status: 409, message: 'Paiement non débité — rien à rembourser.' },
  E1c: { status: 502, message: 'Charge introuvable sur le paiement.' },
  E4:  { status: 409, message: 'Paiement déjà intégralement remboursé.' },
  /** E5 carries the refundable amount after this prefix. */
  E5:  { status: 400, message: 'Montant invalide' },
  E6:  { status: 409, message: 'Un remboursement est déjà en cours sur ce montant cumulé.' },
} as const
export type EngineStep = keyof typeof ENGINE_QUOTES

export const RESUME_QUOTES = {
  expired:     { status: 409, message: 'Reprise impossible : la fenêtre d’idempotence Stripe du remboursement initial a expiré et aucun remboursement n’est retrouvé — réconciliation manuelle requise (aucun second remboursement créé).' },
  listDown:    { status: 502, message: 'Reprise impossible pour l’instant (liste Stripe indisponible) — réessayez.' },
  stripeError: { status: 502, message: 'Erreur paiement, réessayez.' },
  failed:      { status: 409, message: 'Remboursement Stripe en échec — reprise manuelle requise (le transfert inversé n’est pas restauré par Stripe : re-transférer le net au restaurant, puis rembourser sans reverse_transfer).' },
} as const

/** J-M03: the engine's answer to a FRESH refund of the claim's amount on the state's facts. */
export type EngineAnswer = { accepts: true; routed?: boolean } | { accepts: false; step: EngineStep }
/** J-M04: the engine resumes the oldest pending row. */
export type ResumeAnswer = {
  /** G5's evidence class of the oldest row, or 'unreadable' when the loader cannot read the facts. */
  evidence: PendingEvidence | 'unreadable'
  outcome: 'ok' | 'pending_202' | keyof typeof RESUME_QUOTES
}
/** J-M43: what reconcile's N0-N8 writes on an admitted no-row pre-image. */
export type ReconcileAnswer = {
  outcome: 'no_refund_proven' | 'no_refund_proven_rail_locked' | 'no_refund_proven_awaiting_finalization' | 'financial_verification' | 'stripe_unreadable_retry' | 'unconfirmed_within_window'
  reason?: 'refund_moved_unattributed' | 'stripe_refund_contradiction'
  contains?: string[]
}
export type StateFacts = { world: (w: EngineWorld) => void; engine?: EngineAnswer; resume?: ResumeAnswer; reconcile?: ReconcileAnswer }
export type StateEntry = { id: string; registry: RegistryId[]; expected: StateExpected } & Partial<StateFacts>

// ── world helpers ────────────────────────────────────────────────────────────────────────────────
const charge = (w: World) => w.pis.pi_1.latest_charge as Record<string, unknown>
const refunded = (w: World, cents: number) => { charge(w).amount_refunded = cents }
const routedPi = (w: World) => { w.pis.pi_1.transfer_data = { destination: 'acct_r' } }
const settled = (w: World, id: string, rowId: string, o: Record<string, unknown> = {}) =>
  w.claims.push({ id, orderId: 'o1', status: 'refunded', refundAttempted: true, refundId: rowId, refundError: null, requestedAmountCents: 300, ...o })
const ago = (h: number) => new Date(Date.now() - h * HOURS)
const own = 'claim:cl1'

/** Succeeded row + its Stripe refund (both on the order's payment). */
const succeededRow = (w: World, id: string, re: string, key: string, reason: string | null, cents = 300, stripeStatus = 'succeeded') => {
  w.refunds.push(refundRow(id, { status: 'succeeded', stripeRefundId: re, idempotencyKey: key, reason, amountCents: cents }))
  w.stripeRefunds.push(stripeRefund(re, { status: stripeStatus, amount: cents }))
}
/** A row succeeded here whose Stripe refund FAILED (A-S03 / A-S04 / A-S23b / A-S24 / A-S31). */
const revertedRow = (w: World, key: string, reason: string | null = 'claim:cl_OTHER') => succeededRow(w, 'rf_o', 're_O', key, reason, 300, 'failed')
/** A pending row of another claim, tagged at Stripe with `stripeStatus` (null → no Stripe refund). */
const otherPending = (w: World, id: string, hours: number, stripeStatus: string | null, o: Record<string, unknown> = {}) => {
  w.refunds.push(refundRow(id, { status: 'pending', reason: 'claim:cl_O', createdAt: ago(hours), amountCents: 300, ...o }))
  if (stripeStatus) w.stripeRefunds.push(stripeRefund(`re_${id}`, { status: stripeStatus, metadata: { grubano_refund_row: id } }))
}

const LOCK = { outcome: 'no_refund_proven_rail_locked' } as const
const PARK_UNATTRIBUTED = { outcome: 'financial_verification', reason: 'refund_moved_unattributed' } as const
const PARK_CONTRADICTION = { outcome: 'financial_verification', reason: 'stripe_refund_contradiction' } as const
const YES: EngineAnswer = { accepts: true }
const NO = (step: EngineStep): EngineAnswer => ({ accepts: false, step })

