export const STATES: StateEntry[] = Object.keys(TEXT).map((id) => ({ id, ...TEXT[id], ...(FACTS[id] ?? {}) }))
export const stateOf = (id: string): StateEntry => {
  const s = STATES.find((x) => x.id === id)
  if (!s) throw new Error(`no fixture entry for ${id}`)
  return s
}
